fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    
    // If the input array has length 0 or 1, return it unchanged
    if n <= 1 {
        return numbers;
    }

    // Create a new vector with the required size
    let mut result = Vec::with_capacity(2 * n - 1);

    // Iterate through the input numbers and insert them along with the delimiter
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num); // Push the current number
        if i < n - 1 { // Avoid adding delimiter after the last number
            result.push(delimiter); // Push the delimiter
        }
    }

    result
}